<?php
require_once __DIR__ . '/_journey_helpers.php';
try{ if($_SERVER['REQUEST_METHOD']!=='GET'){ApiResponse::send(false,[],'Method not allowed.',[],405);exit;} $db=journeys_db(); $id=(int)($_GET['journey_id']??0); $j=$id>0?journeys_find($db,$id):null; if(!$j||!journeys_can_view($db,$j,journeys_user_id())){ApiResponse::notFound('Journey not found.');exit;} $parts=$db->prepare("SELECT jp.user_id,jp.role,jp.status,u.full_name,u.profile_photo FROM journey_participants jp INNER JOIN users u ON u.id=jp.user_id WHERE jp.journey_id=:id AND jp.status IN ('pending','accepted') ORDER BY jp.role DESC,u.full_name ASC"); $parts->execute(['id'=>$id]); $items=$db->prepare("SELECT ji.*,u.full_name contributor_name FROM journey_items ji INNER JOIN users u ON u.id=ji.contributor_id WHERE ji.journey_id=:id AND ji.deleted_at IS NULL AND ji.status IN ('approved','pending') ORDER BY COALESCE(ji.item_date, DATE(ji.created_at)) ASC, ji.id ASC"); $items->execute(['id'=>$id]); $viewer=journeys_user_id(); $canManage=$viewer!==null&&journeys_can_manage($db,$j,$viewer); $out=[]; foreach($items->fetchAll(PDO::FETCH_ASSOC) as $item){ if(!$canManage && $item['status']!=='approved')continue; if(!journeys_item_visible($db,$item,$viewer))continue; $out[]=journeys_format_item($db,$item);} ApiResponse::success(['journey'=>journeys_format($db,$j),'participants'=>$parts->fetchAll(PDO::FETCH_ASSOC),'items'=>$out],'Journey loaded.'); }catch(Throwable $e){Logger::error('Journey view failed',['error'=>$e->getMessage()]);ApiResponse::serverError('Unable to load journey.');}
?>
